def is_feasible(N, cntA):
    if N % 2 == 0:
        if len(cntA) != N // 2:
            return False

        for i in range(1, N, 2):
            if cntA[i] != 2:
                return False

        return True
    else:
        if len(cntA) != (N + 1) // 2:
            return False

        for i in range(0, (N + 1) // 2, 2):
            if i == 0:
                if cntA[i] != 1:
                    return False
            else:
                if cntA[i] != 2:
                    return False

        return True


