    if n == 0:
        return 1
    if n == 1:
        return b
    else:
        # return b*mpow(b,n-1)
        if n % 2 == 0:
            return mpow(b*b,n//2,mod) % mod
        else:
            return (b % mod) * (mpow(b*b,n//2,mod) % mod)


