from typing import List

def solve(height: int, width: int, pixels: List[str]) -> str:
    extended_pixels: List[str] = []

    for i in range(2 * height):
        extended_i = i // 2
        extended_pixels.append(pixels[extended_i])

    return '\n'.join(extended_pixels)


