def factorization(n) -> dict:
    '''
    素因数分解する．
    '''
    dict_ = {}
    for i in range(2, floor(n**0.5)+1):
        if n % i == 0:
            cnt = 0
            while n % i == 0:
                cnt += 1
                n //= i
            dict_[i] = cnt
    if n != 1:
        dict_[n] = 1
    # if not dict_:
    #     dict_[n] = 1
    return dict_


def meguru_binary_search(ng, ok, isOK) -> int:
    '''
    isOKをみたす端のインデックスを返す．
    ng: 条件をみたさないインデックスの最小値(最大値)
    ok: 条件をみたすインデックスの最大値(最小値)
    isOK: idx -> bool 条件を返す関数
    '''

    while abs(ok-ng) > 1:
        mid = (ok + ng) // 2
        if isOK(mid):
            ok = mid
        else:
            ng = mid
    return ok


def lower_binary_search(a: list, key: int) -> int:
    '''
    リストaのうちkeyのインデックスを返す．
    keyないときはkey以上となる要素の最小値を返す．
    a: 検索対象のリスト
    key: 検索する値
    '''
    def isOK(idx):
        return a[idx] >= key
    return meguru_binary_search(-1, len(a), isOK)


def upper_binary_search(a: list, key: int) -> int:
    '''
    リストaのうちkeyのインデックスを返す．
    keyないときはkey以下となる要素の最大値を返す．
    a: 検索対象のリスト
    key: 検索する値
    '''
    def isOK(idx):
        return a[idx] <= key
    return meguru_binary_search(len(a), -1, isOK)


def input_edge(n: int, m: int, bidirectional=True, with_cost=False) -> list:
    '''
    n頂点，m辺のグラフの辺集合を入力から得る
    n: 頂点の数
    m: 辺の数
    bidirectional: 双方向かどうか
    '''
    edge = [[] for _ in range(n)]

    for _ in range(m):
        a, b = LI()
        a, b = a-1, b-1
        if with_cost:
            to_a = (a, 1)
            to_b = (b, 1)
        else:
            to_a = a
            to_b = b
        edge[a].append(to_b)
        if bidirectional:
            edge[b].append(to_a)
    return edge


def input_edge_with_cost(n: int, m: int, bidirectional=True) -> list:
    '''
    n頂点，m辺のグラフの重み付き辺集合を入力から得る
    n: 頂点の数
    m: 辺の数
    bidirectional: 双方向かどうか
    '''
    edge = [[] for _ in range(n)]

    for _ in range(m):
        a, b, c = LI()
        a, b = a-1, b-1
        edge[a].append((b, c))
        if bidirectional:
            edge[b].append((a, c))
    return edge


def input_adjacency_matrix(n: int, m: int, bidirectional: bool = True):
    mat = [[inf]*n for _ in range(n)]
    for _ in range(m):
        a, b, c = LI()
        a, b = a-1, b-1
        mat[a][b] = c
        if bidirectional:
            mat[b][a] = c
    for i in range(n):
        mat[i][i] = 0
    return mat


def bfs(edge: list, start: int) -> list:
    '''
    辺集合edgeで表されるグラフについてstartからの距離のリストを返す．
    edge: 各頂点から伸びているコスト付き辺の集合
    start: 始点
    '''
    dist = [-1]*len(edge)
    que = deque([start])
    dist[start] = 0

    while que:
        v = que.popleft()
        d = dist[v]
        for w, c in edge[v]:
            if dist[w] > -1:
                continue
            else:
                dist[w] = d+c
                que.append(w)
    return dist


def dijkstra(edge: list, start: int) -> list:
    '''
    ダイクストラ法によって最短距離とその経路における直前の頂点を返す．
    計算量は(m+n)logn
    edge: 重み付き辺集合
    start: 始点
    '''
    n = len(edge)
    dist = [inf]*n
    prev = [-1]*n

    q = [(0, start)]
    dist[start] = 0
    while q:
        v = heappop(q)[1]
        for w, c in edge[v]:
            if dist[v]+c < dist[w]:
                dist[w] = dist[v]+c
                prev[w] = v
                heappush(q, (dist[w], w))
    return dist, prev


def warshall_floyd(adjacency_matrix: list) -> list:
    '''
    ワーシャルフロイド法によって最短距離を求める．
    計算量はn^3
    adjacency_matrix: 隣接行列
    start: 始点
    '''
    dist = copy(adjacency_matrix)
    n = len(dist)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j] = min(dist[i][j], dist[i][k]+dist[k][j])
    return dist


def radius_of_tree(edge: list) -> int:
    '''
    辺集合edgeで表される木の直径を返す．
    edge: 各頂点から伸びている重み付き辺のリスト
    '''
    dist = bfs(edge, 0)
    v = dist.index(max(dist))

    dist = bfs(edge, v)
    radius = max(dist)
    return radius


