def prime_factorization(n):
    prime_numbers = Counter()

    for i in range(2, int(sqrt(n)) + 1):
        if n % i != 0:
            continue

        prime_numbers[i] = 0
        while n % i == 0:
            prime_numbers[i] += 1
            n = n // i

    if n != 1:
        prime_numbers[n] = 1

    return prime_numbers


