    n = int(input())

    prime_numbers = Counter()
    for i in range(n):
        prime_numbers += prime_factorization(i + 1)

    count = 1
    for v in prime_numbers.values():
        count = (count * ((v + 1) % MOD)) % MOD

    print(count)


