def prime_factorize(number: int) -> List[int]:
    res = []
    for num in range(2, int(number)+1):
        count = 0
        if number % num != 0: continue
        while number % num == 0:
            count += 1
            number /= num
        for _ in range(count):
            res.append(num)
    if number != 1: res.append(N)
    return res


def divisor_sum(number: int) -> int:
    res = 1
    factorize_dict = Counter(prime_factorize(number))
    for num, count in factorize_dict.items():
        tmp = 0
        for i in range(count+1):
            tmp += num ** i
        res *= tmp
    return res


def divisor_count(number: int) -> int:
    res = 1
    factorize_dict = Counter(prime_factorize(number))
    for i in factorize_dict.values():
        res *= (i+1)
    return res


def euler_func(number: int) -> int:
    res = number
    factorize_dict = Counter(prime_factorize(number))
    for num in factorize_dict.keys():
        res *= (1 - (1 / num))
    return int(res)



