def create_factorizer_with_sieve(n: int):
    """エラトステネスの篩を用いた素因数分解🐍. O(n loglog n)

    Args:
        n (int): 最大数

    Returns:
        int -> dict: 素因数分解をする関数
    """
    # sieve of eratosthenes
    # O(n loglog n)
    sieve = [0] * (n + 1)
    sieve[1] = 1
    for i in range(2, int(n**0.5) + 1):
        if sieve[i] != 0:
            continue
        for j in range(i, n + 1, i):
            sieve[j] = i

    def factorization(m: int) -> dict:
        # O(log n)
        dic = {}
        if m == 1:
            return {1: 1}

        while m > 1:
            if sieve[m] == 0:
                sieve[m] = m

            if sieve[m] in dic:
                dic[sieve[m]] += 1
            else:
                dic[sieve[m]] = 1
            m //= sieve[m]

        return dic

    return factorization


