def solve(N):

    mod = 10 ** 9 + 7

    isprime = [True] * (N+1)
    for i in range(2, int(N**.5)+1):
        if not isprime[i]: continue
        for j in range(i*i, N+1, i):
            isprime[j] = False

    res = 1
    for i in range(2, N+1):
        if isprime[i]:
            powi = i
            sub = 1
            while powi <= N:
                sub += N // powi
                powi *= i
            res *= sub
            res %= mod

