from functools import partial


class Mint:
    def __init__(self, x, mod=10**9 + 7):
        self.x = x.x if isinstance(x, Mint) else x % mod
        self.mod = mod
        self._mint = partial(Mint, mod=mod)

    @staticmethod
    def xgcd(a, b):
        """ return (g, x, y) such that a*x + b*y = g = gcd(a, b) """
        x0, x1, y0, y1 = 0, 1, 1, 0
        while a != 0:
            (q, a), b = divmod(b, a), a
            y0, y1 = y1, y0 - q*y1
            x0, x1 = x1, x0 - q*x1
        return b, x0, y0

    def modinv(self, n):
        g, x, _ = self.xgcd(n, self.mod)
        assert g == 1
        return x % self.mod

    def __str__(self):
        return str(self.x)

    def __repr__(self):
        return repr(self.x)

    def __eq__(self, x):
        return self.x == self._mint(x).x

    def __ne__(self, x):
        return self.x != self._mint(x).x

    def __int__(self):
        return self.x

    def __index__(self):
        return self.x

    def __add__(self, x):
        return self._mint(self.x + self._mint(x).x)

    def __radd__(self, x):
        return self._mint(self.x + self._mint(x).x)

    def __sub__(self, x):
        return self._mint(self.x - self._mint(x).x)

    def __rsub__(self, x):
        return self._mint(self._mint(x).x - self.x)

    def __mul__(self, x):
        return self._mint(self.x * self._mint(x).x)

    def __rmul__(self, x):
        return self._mint(self.x * self._mint(x).x)

