    if n == 1:
        print(1)
        return

    cnt = Counter({})
    for i in range(1, n + 1):
        cnt += Counter(factorize(i))
    ans = reduce(lambda x, y: (x * y) % MAX_MOD, map(lambda x: x + 1, cnt.values()))
    print(ans)


