import sys

def main(f):
    N, M = map(int, f.readline().split())
    A = [f.readline()[:-1] for i in range(N)]
    B = [f.readline()[:-1] for i in range(M)]

    if N == M:
        flag = True
        for i in range(N):
            if A[i] != B[i]:
                return "No"
        return "Yes"

    for i in range(N - M):
        for j in range(N - M):
            flag = True
            for k in range(M):
                for l in range(M):
                    if A[i + k][j + l] != B[k][l]:
                        flag = False
            if flag:
                return "Yes"
    return "No"

if __name__ == '__main__':
    print(main(sys.stdin))
