    n, m = map(int, input().split())
    a = []
    for _ in range(n):
        a.append(input())
    b = []
    for _ in range(m):
        b.append(input())

    # solve problem
    judge = False
    for i in range(n - m + 1):      # move in image a
        for j in range(n - m + 1):
            judge = True
            for x in range(m):      # matching ?
                for y in range(m):
                    if a[y + i][x + j] != b[y][x]:
                        judge = False
                        break       # loop y
                if judge == False:
                    break           # loop x
            if judge == True:
                break               # loop j
        if judge == True:
            break                   # loop i

    # output
    if judge == True:
        print("Yes")
    else:
        print("No")

