def same(ns: tuple, m: int, Ass: list, Bss: list) -> bool:
    ni, nj = ns
    for mi in range(m):
        for mj in range(m):
            if Ass[ni + mi][nj + mj] != Bss[mi][mj]:
                return False

    return True


