def f(G, path, n):
    if len(path) == n:
        return 1
    else:
        start = path[-1]
        ans = 0
        for nnode in G[start]:
            isused = False
            for i in path:
                if i == nnode:
                    isused = True

            if isused:
                continue

            path.append(nnode)
            ans += f(G, path, n)
            path.pop()

        return ans

