def lmap(func, iter):
    return list(map(func, iter))


def main():
    n, m = map(int, input().split())
    ABs = [lmap(int, input().split()) for _ in range(m)]

    adjs = [[] for _ in range(n)]
    for a, b in ABs:
        adjs[a - 1].append(b - 1)
        adjs[b - 1].append(a - 1)

    def dfs(vi: int, used: list) -> int:
        if all(used):
            return 1

        cnt = 0
        for vj in adjs[vi]:
            if not used[vj]:
                newused = used[:]
                newused[vj] = 1
                cnt += dfs(vj, newused)

        return cnt

