import copy
result_count = 0


def dfs(position: int, point_list: list, passing_list: list, limit_size: int):
    global result_count
    if position in passing_list:
        return
    else:
        copy_passing_list = copy.deepcopy(passing_list)
        copy_passing_list.append(position)

        if len(copy_passing_list) == limit_size:
            result_count += 1
            return
        for value in point_list[position]:
            dfs(value, point_list, copy_passing_list, limit_size)


