def find(data,i,k,N):
  an=0
  if k==2**N-1:
    return 1
  for j in range(len(data[i])):
    jj=data[i][j]
    if  not (k>>jj & 1):
      an+=find(data,jj,k|(1<<jj),N)
  return an

