import sys


def solve(N: int, M: int, a: "List[int]", b: "List[int]"):
    edges = [[] for _ in range(N)]
    for aa, bb in zip(a, b):
        edges[aa-1].append(bb-1)
        edges[bb-1].append(aa-1)

    def dfs(node, visited):
        if visited == (1<<N) - 1:
            return 1
        res = 0
        for n in edges[node]:
            if visited & (1<<n) > 0:
                continue
            res += dfs(n, visited|(1<<n))
        return res

    return dfs(0, 1)


