def search_vertex(graph:list, vertex_list):
    for vertex in vertex_list:
        if len(graph) == 1:
            break
        first = vertex[0] - 1
        second = vertex[1] - 1
        if graph[0] == first and graph[1] == second:
            graph.pop(0)
            search_vertex(graph, vertex_list)
        elif graph[1] == first and graph[0] == second:
            graph.pop(0)
            search_vertex(graph, vertex_list)

