def getNumSolutions(vertex, visited, N, actions):

    visited.append(vertex)

    if len(visited) == N:
        return 1

    total = 0

    for neighbor in actions[vertex]:
        if neighbor not in visited:
            total += getNumSolutions(neighbor, visited[:], N, actions)

    return total

