    current = path[-1]
    if len(path) == n:
        path = tuple(path)
        if path not in res:
            res.add(path)
            return
    else:
        for neighbor in graph[current]:
            if neighbor not in path:
                path.append(neighbor)
                dfs(graph,path,n,res)
                path.pop()
    return


