def prepare():
    sx, sy, tx, ty = map(int, input().split(" "))
    return [sx, sy, tx, ty]


def find_shortest_routes(S):
    sx, sy, tx, ty = S
    outward1 = ["U"] * (ty - sy) + ["R"] * (tx - sx)
    return1 = ["D"] * (ty - sy) + ["L"] * (tx - sx)
    outward2 = ["L"] + ["U"] * (ty - sy + 1) + ["R"] * (tx - sx + 1) + ["D"]
    return2 = ["R"] + ["D"] * (ty - sy + 1) + ["L"] * (tx - sx + 1) + ["U"]
    routes = outward1 + return1 + outward2 + return2
    for i, m in enumerate(routes):
        if i != len(routes) - 1:
            print(m, end="")
        else:
            print(m)


if __name__ == "__main__":
    S = prepare()
    find_shortest_routes(S)

