from collections import deque


dh = [1, 0, -1, 0]
dw = [0, 1, 0, -1]


sx, sy, tx, ty = list(map(int, input().split()))
tx -= (sx - 1)
ty -= (sy - 1)
sx, sy = 1, 1
H, W = ty + 3, tx + 3
G = [[0] * W for _ in range(H)]


def restore_route(sh, sw, gh, gw, dist):
    h, w = gh, gw
    res = ''
    d = ['D', 'L', 'U', 'R']
    while h != sh or w != sw:
        for i in range(4):
            nh = h + dh[i]
            nw = w + dw[i]
            if nh < 0 or nw < 0 or nh >= H or nw >= W:
                continue
            if G[nh][nw]:
                continue
            if dist[h][w] - dist[nh][nw] == 1:
                res = d[i] + res
                if nh != sh or nw != sw:
                    G[nh][nw] = 1
                h, w = nh, nw
                break
    return res


def main():
    ans = ''
    for i in range(4):
        if i % 2 == 0:
            sh, sw = sy, sx
            gh, gw = ty, tx
        else:
            sh, sw = ty, tx
            gh, gw = sy, sx

        dist = [[-1] * W for _ in range(H)]
        dist[sh][sw] = 0
        que = deque([(sh, sw)])

        while que:
            h, w = que.popleft()
            for i in range(4):
                nh = h + dh[i]
                nw = w + dw[i]
                if nh < 0 or nw < 0 or nh >= H or nw >= W:
                    continue
                if G[nh][nw]:
                    continue
                if dist[nh][nw] == -1:
                    dist[nh][nw] = dist[h][w] + 1
                    que.append((nh, nw))

        ans += restore_route(sh, sw, gh, gw, dist)

    print(ans)


if __name__ == "__main__":
    main()

