    A = read_ints()
    answer = 0
    for i in range(1, N):
        if A[i-1]+A[i] > x:
            eat = A[i]+A[i-1]-x
            if eat <= A[i]:
                A[i] -= eat
                answer += eat
            else:
                eat -= A[i]
                answer += A[i]
                A[i] = 0
                A[i-1] -= eat
                answer += eat
    return answer


