from typing import Dict


def divide_by_two(before: Dict[int, int]) -> Dict[int, int]:
    # keys: divided value
    # values: original value (doesn't change)

    new_collection = {}

    for remainder in before.keys():
        if remainder % 2 == 0:
            new_collection[remainder // 2] = before[remainder]

    return new_collection

def solve(upbound: int) -> int:
    if upbound <= 1:
        return upbound

    even_nums = list(filter(lambda num: num % 2 == 0, list(range(1, upbound + 1))))

    candidates = { n: n for n in even_nums }

    while len(candidates.keys()) > 1:
        candidates = divide_by_two(candidates)

    return list(candidates.values())[0]

