def solve(N: int):
    answer = N
    maximum = 0
    for i in range(1, N + 1):
        num = 0
        temp_i = i
        while temp_i % 2 == 0:
            temp_i /= 2
            num += 1
        if num > maximum:
            maximum = num
            answer = i
    print(answer)
    return


