from sys import stdin
from collections import deque


def bfs(graph, n):
    dist = [-1] * n
    dist[0] = 0
    next_visit = deque([0])
    while next_visit:
        cur = next_visit.popleft()
        for i in graph[cur]:
            if dist[i] > -1:
                continue
            dist[i] = dist[cur] + 1
            next_visit.append(i)

    return dist


