import numpy as np
import sys
from heapq import heappop, heappush

class Dijkstra:
    def __init__(self, n):
        self.ans = [-1] * n
        self.pre = [None] * n

    def dijkstra(self, G, start = 0):
        self.ans[start] = 0
        candidate = []
        for g in G[start]:
            heappush(candidate, g + (start, ))
        while candidate:
            m, i, p = heappop(candidate)
            if self.ans[i] >= 0:
                continue
            self.ans[i] = m
            self.pre[i] = p
            for (w, g) in G[i]:
                if self.ans[g] == -1:
                    heappush(candidate, (m + w, g, i))
                else:
                    pass

    def route(self, s, g):
        if self.pre[g] == None: return str(s)
        return self.route(s, self.pre[g]) + ' ' + str(g)


def main():
    n, m = map(int, input().split())
    AB = np.fromstring(sys.stdin.read(), np.int64, sep=' ').reshape(-1,2) - 1
    G = [[] for _ in range(n)]
    for a, b in zip(*AB.T):
        G[a].append((1, b))
        G[b].append((1, a))
    d = Dijkstra(n)
    d.dijkstra(G, 0)
    print('POSSIBLE' if d.ans[-1] == 2 else 'IMPOSSIBLE')

