    for i in range(M):
        if(A[i] == 1):
            OneFrom_append(B[i]-1)
    OneFrom = sorted(OneFrom)
    ToN = []
    ToN_append = ToN.append
    for i in range(M):
        if(B[i] == N):
            ToN_append(N-A[i])
    ToN = sorted(ToN)
    Goal = N-1
    One = len(OneFrom)
    GoN = len(ToN)
    if(One> 0 and GoN >0):
        for i in range(One):
            def is_ok(arg):
                return OneFrom[i] + ToN[arg] <= Goal
            Index = meguru_bisect(GoN, -1)
