import sys

sys.setrecursionlimit(200000)


class Solver:
    def input(self):
        """
        faster input function than builtin stdin.
        """
        return sys.stdin.readline()[:-1]

    def ii(self, t: type = int):
        """
        input single value.
        """
        return t(self.input())

    def il(self, t: type = int):
        """
        input single line.
        """
        return list(map(t, self.input().split()))

    def imi(self, N: int, t: type = int):
        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        N, M = self.il()
        E = set()
        for m in range(M):
            a, b = self.il(str)
            E.add(a + b)

        for n in range(2, N):
            if f"1{n}" in E and f"{n}{N}" in E:
                return "POSSIBLE"
        return "IMPOSSIBLE"


if __name__ == "__main__":
    solver = Solver()
    print(solver.solve())

