import sys
import math
import itertools

def eratosthenes(n):
    numbers = [-1] * (n+1)
    numbers[0] = -1
    numbers[1] = -1
    for i in range(2,n+1):
        if numbers[i] != -1:
            continue
        for j in range(i,n+1,i):
            numbers[j] = i
    return numbers

def eratosthenesPrimes(n):
    e = eratosthenes(n)
    return [i for i in range(n+1) if e[i] == i]

def factor(n,primes):
    result = []
    for p in primes:
        if n == 1:
            break
        while n%p == 0:
            n//=p
            result.append(p)
    if n != 1:
        result.append(n)
    return result


def solve(N: int):
    primes = eratosthenesPrimes(math.ceil(math.sqrt(N)))
    f = factor(N,primes)
    result = 10**16
    for i in range(1 << len(f)):
        A = 1
        for j in range(len(f)):
            if (1<<j)&i > 0:
                A *=f[j]
        B = N//A
        r = max(math.floor(math.log10(A)) + 1,math.floor(math.log10(B)) + 1)
        result = min(r,result)

    print(result)
    return


