def get_one_factor(n: int) -> int:
    """
    一つの素因数を計算する
    計算量は O(sqrt(n))
    """
    for k in range(2, int(sqrt(n)) + 1):
        if n % k == 0:
            return k

    return n


def compute_factors(n: int):
    """
    素因数分解を計算する
    計算量は O(sqrt(n)log(n))
    """
    while n > 1:
        k = get_one_factor(n)
        count = 0
        while n % k == 0:
            n //= k
            count += 1

        yield (k, count)


def compute_divisors(n: int):
    """
    nの約数の一覧を返す
    計算量は?
    """
    factors = list(compute_factors(n))
    factor_nums = [num for num, _ in factors]
    factor_counts = [count for _, count in factors]

    for counts in product(*(range(c + 1) for c in factor_counts)):
        p = 1
        for num, cnt in zip(factor_nums, counts):
            p *= num**cnt
        yield p


