          f = flow_to_sink(v, min(flow_in, e.capacity))
          if not f: continue
          self.edges[u][v].capacity -= f
          if u in self.edges[v]: self.edges[v][u].capacity += f
          else: self.add_edge(v, u, capacity=f)
          flow_in -= f
          flow += f
        return flow

