    cnt = 0
    for i in range(arr_length):
        # マイナス計算
        if (i+turn) % 2 == 0:
            if tmp_sum+arr[i] >= 0:
                cnt += abs(arr[i]-(-tmp_sum-1))
                arr[i] = -tmp_sum-1
        #プラス計算
