def soinsu(n):
  ans = []
  num = n
  for i in range(2, int(-(-n**0.5//1))+1):
    if num%i == 0:
      coun = 0
      while num%i == 0:
        coun += 1
        num //= i
      ans.append([i,coun])
  if num != 1:
    ans.append([num,1])
  if ans == []:
