def calc(n: int, a):
    ret = 0
    ruiseki = 0
    for i in range(n):
        x = a[i]
        if i % 2 == 0:
            if ruiseki + x >= 1:
                ruiseki += x
            else:
                ret += 1 - (ruiseki + x)
                ruiseki = 1
        else:
            if ruiseki + x <= -1:
                ruiseki += x
            else:
                ret += 1 + (ruiseki + x)
                ruiseki = -1
    return ret

def solve(n:int, a):
    ans1 = calc(n, a)
    ans2 = calc(n, [-x for x in a])
    print(min(ans1,ans2))
    return

