def I(): return input().rstrip()
def IS(): return input().split()
def II(): return int(input())
def IIS(): return map(int, input().split())
def LIIS(): return list(map(int, input().split()))


def main():
    N = II()
    a = LIIS()
    pro = 0
    ans = 0
    dic = {}
    for i in range(N):
        tmp = a[i]
        if tmp < 400:
            dic["gray"] = 1
        elif tmp < 800:
            dic["brown"] = 1
        elif tmp < 1200:
            dic["green"] = 1
        elif tmp < 1600:
            dic["lblue"] = 1
        elif tmp < 2000:
            dic["blue"] = 1
        elif tmp < 2400:
            dic["yellow"] = 1
        elif tmp < 2800:
            dic["orange"] = 1
        elif tmp < 3200:
            dic["red"] = 1
        else:
            pro += 1
    ans += len(dic)
    if ans == 0:
        m = 1
    else:
        m = ans
    M = len(dic)+pro
    print(str(m)+" "+str(M))


if __name__ == "__main__":
    main()

