import sys

sys.setrecursionlimit(200000)


class Solver:
    def input(self):
        """
        faster input function than builtin stdin.
        """
        return sys.stdin.readline()[:-1]

    def ii(self, t: type = int):
        """
        input single value.
        """
        return t(self.input())

    def il(self, t: type = int):
        """
        input single line.
        """
        return list(map(t, self.input().split()))

    def imi(self, N: int, t: type = int):
        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        N = self.ii()
        A = self.il()
        color = set()
        god = 0
        for a in A:
            if a >= 3200:
                god += 1
            else:
                color.add(a // 400)
        return f"{max(len(color), 1)} {len(color) + god}"


if __name__ == "__main__":
    solver = Solver()
    print(solver.solve())

