import sys
import math


def solve(N: int, a: "List[int]"):
    ans = set()
    red = 0
    for i in a:
        if i >= 3200:
            red += 1
        else:
            ans.add(math.floor(i / 400))
    print(max(len(ans), min(1, red)), len(ans) + red)
    return


