def solve(a):
    color = defaultdict(int)

    for aa in a:
        if aa < 3200:
            color[aa//400] += 1
        else:
            color[8] += 1

    min_ans = len(color)
    max_ans = len(color)

    if 8 in color:
        min_ans = max(1, min_ans-1)
        max_ans += color[8] - 1

    return str(min_ans), str(max_ans)


