def make_divisors(x):
    l_div, u_div = [], []
    i = 1
    while i * i <= x:
        if x % i == 0:
            l_div.append(i)
            if i != x // i:
                u_div.append((x // 1))
        i += 1
    return l_div + u_div[::-1]


def reverse(S):
    X = []
    str = ""
    for i in range(len(S)):
        i += 1
        X.append(S[-i])

    return str.join(X)


def permutation(l):
    return list(it.permutations(l))


def combination(l, p):
    return list(it.combinations(l, p))


def getNearestNum(l, n):
    idx = np.abs(np.asarray(l) - n).argmin()
    return l[idx]


