class UnionFind():
    def __init__(self, N):
        self.N = N
        self.par = [-1] * N

    def __len__(self):
        return len(self.roots())

    def find(self, x):
        if self.par[x] < 0:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y:
            return
        if self.par[x] > self.par[y]:
            x, y = y, x
        self.par[x] += self.par[y]
        self.par[y] = x

    def size(self, x):
        return -self.par[self.find(x)]

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def roots(self):
        return [i for i, x in enumerate(self.par) if x < 0]


def main():
    t = UnionFind(13)
    t.unite(1, 3)
    t.unite(1, 5)
    t.unite(1, 7)
    t.unite(1, 8)
    t.unite(1, 10)
    t.unite(1, 12)
    t.unite(4, 6)
    t.unite(4, 9)
    t.unite(4, 11)
    x, y = IIS()
    print('Yes' if t.same(x, y) else 'No')


