import sys

sys.setrecursionlimit(200000)


class Solver:
    def input(self):
        """
        faster input function than builtin stdin.
        """
        return sys.stdin.readline()[:-1]

    def ii(self, t: type = int):
        """
        input single value.
        """
        return t(self.input())

    def il(self, t: type = int):
        """
        input single line.
        """
        return list(map(t, self.input().split()))

    def imi(self, N: int, t: type = int):
        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        X, Y = self.il()
        A = set([1, 3, 5, 7, 8, 10, 12])
        B = set([4, 6, 9, 11])
        C = set([2])

        if X in A and Y in A:
            return "Yes"
        if X in B and Y in B:
            return "Yes"
        if X in C and Y in C:
            return "Yes"
        return "No"


if __name__ == "__main__":
    solver = Solver()
    print(solver.solve())

