import sys

def debug_print(*args):
    print(args, file = sys.stderr)

def acc(arr, M, inizero = False):
    a = [0]
    for ar in arr:
        a.append((a[-1] + ar) % M)
    if not inizero:
        a = a[1:]
    return a

# Queryを並び変えて問題を解くときは、答えのインデックスを3つめに追加しておく
def input_query_data(Q):
    f = sys.stdin
    LR = []
    for q in range(Q):
        l, r = map(int, f.readline().split())
        LR.append([l, r, q])
    return LR

def init_tbl(H, W, val=0):
    return [[val] * W for i in range(H)]

# 「#」がもの、「.」が何もないとすると、一回り周辺を「.」で埋める
# マップを作成する。「.」が0で「#」が1を表す
def create_map(H, W):
    f = sys.stdin
    S = [f.readline().rstrip() for i in range(H)]
    tbl = [[0] * (W + 2) for i in range(H + 2)]
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            tbl[i][j] = 0 if S[i - 1][j - 1] == "." else 1
    return tbl

def counter_elem(l):
    from collections import Counter
    return Counter(l)

def main():
    f = sys.stdin
    S = f.readline().rstrip()
    count = counter_elem(S)
    for v in count.values():
        if v % 2 != 0:
            return "No"
    return "Yes"

def resolve():
    print(main())
