from typing import Dict
from functools import reduce

def solve(string: str) -> str:
    # if string's length is odd
    if len(string) & 1:
        return 'No'

    # count characters
    char_counts: Dict[str, int] = {}
    for char in string:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    any_odd = reduce(lambda is_all_even, char_count: is_all_even or (char_count & 1), char_counts.values(), 0)

    return 'No' if any_odd else 'Yes'

