def solve(N: int, T: int, t: "List[int]"):
    a = [[t[0]]]
    for tt in t[1:]:
        if a[-1][-1] + T < tt:
            a.append([tt])
        else:
            a[-1].append(tt)
    b = [aa[-1] - aa[0] + T for aa in a]    
    return sum(b)


