import sys
from collections import deque
def input(): return sys.stdin.readline().strip()

def main():
    N, T = map(int, input().split())
    A = deque(map(int, input().split()))
    time = 0
    start = 0
    stop = 0
    while A:
        a = A.popleft()
        if stop < a:
            time += stop - start
            start = a
            stop = a + T
        else:
            stop = a + T
    print(time + stop - start)


