def solve(N: int, T: int, t: "List[int]"):
    start = 0
    ans = 0
    for i in range(N - 1):
        d = t[i + 1] - t[i]
        if T >= d:
            continue
        ans += t[i] - start + T
        start = t[i + 1]
    ans += t[-1] - start + T
    print(ans)
    return


