def solve(N, S):
    ans = []
    pre = 0
    for s in S:
        if s == '(':
            pre += 1
            ans.append(s)
        else:
            if pre == 0:
                ans.insert(0, '(')
                ans.append(s)
            else:
                ans.append(s)
                pre -= 1
    ans += [')'] * pre
    return ''.join(ans)

