def resolve():
  N = int(input())
  S = list(input())

  # "(" は左端に、")" は右端に入れることになるので、既にペアになってない "(" と ")" を数えれば良い。
  free_left_count = 0
  free_right_count = 0
  for s in S:
    if s=="(":
      free_left_count+=1
    else:
      if free_left_count:
        free_left_count-=1
      else:
        free_right_count+=1

  print("("*free_right_count + "".join(S) + ")"*free_left_count)

resolve()

