def DFS(g, s, n, pos=None, kei=None):
    if pos is None:
        pos = set()
    if kei is None:
        kei = []
    kei = copy(kei)
    kei += [s]
    pos.add(s)
    if s == n:
        global keiro
        keiro = kei
        return False
    for i in g[s]:
        if not (i in pos):
            if not DFS(g, i, n, pos, kei):
                return False
    return pos


