def mypow(a, b, modz):
    ret = 1
    while b > 0:
        if b & 0x01:
            ret = (ret * a) % modz
            b -= 1
        else:
            b >>= 1
            a = (a * a) % modz
    return ret


# sturin 2nd theory
# S(n,k)=kS(n−1,k)+S(n−1,k−1)
def S(n, k, modz):
    sumz = 0

    sign = 1 if (k & 0x01 == 0) else -1
    for i in range(k + 1):
        if sign > 0:
            sumz = (sumz + (nCk(k, i, modz) * mypow(i, n, modz)) % modz) % modz
        else:
            sumz = (sumz + (modz - nCk(k, i, modz) * mypow(i, n, modz) % modz)) % modz

        sign = -sign
    return fact_inv[k] * sumz % modz

