    n = int(input())
    sentences = []
    while True:
        try:
            sentences.append(sorted(input(), reverse=True))
        except EOFError:
            break

    pocket = sentences[0].copy()

    for n, sentence in enumerate(sentences):
        pocket = seki(pocket, sentence)

    print(''.join(sorted(pocket)))


