import sys


def solve(n: int, S: "List[str]"):
    from collections import Counter
    from functools import reduce
    from itertools import chain
    def common(c0, c1):
        return Counter({c: min(c0[c], c1[c]) for c in set(chain(c0.keys(), c1.keys()))})
    return sorted(reduce(common, map(Counter, S)).elements())

