        Returns a list of distance. If starts contains more than one vertex, returns the shortest distance from any of them
        """
        dist = [-1] * self.n_vertices

        if isinstance(s, int):
            q = [s]
            dist[s] = 0
        else:
            q = list(s)
            for v in q:
                dist[v] = 0
        for d in range(1, self.n_vertices):
            nq = []
            for v in q:
                for u in self.adj(v):
                    if dist[u] == -1:
                        dist[u] = d
                        nq.append(u)
                    if u == t:
                        return dist
            q = nq
        return dist

    def dist(self, s, t, inf=INF):
        return self.bfs(s, t)[t]


