class BaseRootedTree(BaseGraph):

    def __init__(self, n_vertices, root_vertex=0):
        super().__init__(n_vertices)
        self.root = root_vertex

    def parent(self, v):
        raise NotImplementedError

    def children(self, v):
        raise NotImplementedError

    def adj(self, v):
        if self.root == v:
            return self.children(v)
        return itertools.chain(self.children(v), (self.parent(v),))

    @property
    def post_order(self):
        """
        bottom vertices first
        """
        return (~v for v in self.prepost_order if v < 0)

    @property
    def pre_order(self):
        """
        top vertices first
        """
        return (v for v in self.prepost_order if v >= 0)

    @property
    def prepost_order(self):
        """
        if v >= 0: it's pre-order entry
        otherwise: it's post-order entry
        """
        try:
            return self._prepost_order
        except AttributeError:
            order = [0] * (self.n_vertices * 2)
            stack = [~self.root, self.root]
            i = 0
            for i in range(self.n_vertices * 2):
                v = stack.pop()
                order[i] = v
                if v >= 0:
                    for u in self.children(v):
                        stack.append(~u)
                        stack.append(u)
            self._prepost_order = order
            return order

    @property
    def prepost_indices(self, cache=False):
        try:
            return self._pre_ind, self._post_ind
        except AttributeError:
            pre_ind = [0] * self.n_vertices
            post_ind = [0] * self.n_vertices
            for i, t in enumerate(self.prepost_order):
                if t >= 0:
                    pre_ind[t] = i
                else:
                    post_ind[~t] = i
            self._pre_ind = pre_ind
            self._post_ind = post_ind
            return pre_ind, post_ind

    def depth(self, v):
        try:
            return self._depth[v]
        except AttributeError:
            depth = [0] * (self.n_vertices)
            l = 0
            for k in self.prepost_order:
                if k >= 0:
                    depth[k] = l
                    l += 1
                else:
                    l -= 1
            self._depth = depth
            return depth[v]

    @property
    def height(self):
        try:
            return self._height
        except AttributeError:
            self._height = max(self.depth(v) for v in range(self.n_vertices)) + 1
            return self._height

    @property
    def doubling(self):
        try:
            return self._dbl
        except AttributeError:
            d = self.height.bit_length()

            dbl = Array2d.full(self.n_vertices, d, -1)
            for v in self.pre_order:
                u = self.parent(v)
                dbl[v, 0] = u
                for i in range(d - 1):
                    u = dbl[u, i]
                    if u < 0:
                        break
                    dbl[v, i + 1] = u
            self._dbl = dbl
            return dbl

    def ancestor_of(self, v, k):
        dbl = self.doubling
        if k > self.depth(v):
            return -1
        i = 0
        while k:
            if k & 1:
                v = dbl[v, i]
            k //= 2
            i += 1
        return v

    def lca(self, u, v):
        lu, lv = self.depth(u), self.depth(v)
        if lu > lv:
            u = self.ancestor_of(u, lu - lv)
        else:
            v = self.ancestor_of(v, lv - lu)
        if u == v:
            return u

        dbl = self.doubling
        i = dbl.m - 1
        while True:
            while i >= 0 and dbl[u, i] == dbl[v, i]:
                i -= 1
            if i < 0:
                return dbl[u, 0]
            u, v = dbl[u, i], dbl[v, i]

    def dist(self, u, v, inf=INF):
        return self.depth(u) + self.depth(v) - 2 * self.depth(self.lca(u, v))

    def solve_rerooting(self, merge, identity, finalize):
        """
        merge: (T,T) -> T, (T, merge)はモノイド
        identity: 単位元
        finalize: (T, V, V) -> T

        以下の形で書けるdpは対応可能
        dp[u,v] = finalize(merge(dp[v,k] for k in adj[v] if k != u), u, v)
        ただし(u,v)は辺
        dp[u,v]: vを根とするuを含まないような部分木についての解
        """

        dp1 = [identity] * self.n_vertices
        dp2 = [identity] * self.n_vertices

        for v in self.post_order:
            t = identity
            for u in self.children(v):
                dp2[u] = t
                t = merge(t, finalize(dp1[u], v, u))
            t = identity
            for u in reversed(list(self.children(v))):
                dp2[u] = merge(t, dp2[u])
                t = merge(t, finalize(dp1[u], v, u))
            dp1[v] = t
        for v in self.pre_order:
            if v == self.root:
                continue
            p = self.parent(v)
            dp2[v] = finalize(merge(dp2[v], dp2[p]), v, p)
            dp1[v] = merge(dp1[v], dp2[v])
        return dp1


class RootedTree(BaseRootedTree):

    @classmethod
    def from_edges(cls, edges, root_vertex=0):
        rt = cls(len(edges) + 1, root_vertex)
        adj = [[] for _ in range(rt.n_vertices)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        rt._adj = adj
        rt._edges = edges
        return rt

    @classmethod
    def from_parent(cls, parent, root_vertex):
        rt = cls(len(parent), root_vertex)
        rt._parent = parent
        return rt

    @classmethod
    def random(cls, n_vertices, root_vertex=0):
        parent = [-1] * n_vertices
        vertices = list(range(root_vertex)) + list(range(root_vertex + 1, n_vertices))
        shuffle(vertices)
        vertices.append(root_vertex)
        for i, v in zip(reversed(range(n_vertices)), vertices[-2::-1]):
            parent[v] = vertices[randrange(i, n_vertices)]
        return cls.from_parent(parent, root_vertex)

    def adj(self, v):
        try:
            return self._adj[v]
        except AttributeError:
            if v == self.root:
                return self.children(v)
            return itertools.chain(self.children(v), (self.parent(v),))

    def parent(self, v):
        try:
            return self._parent[v]
        except AttributeError:
            parent = [0] * self.n_vertices
            parent[self.root] = -1
            stack = [self.root]
            for _ in range(self.n_vertices):
                k = stack.pop()
                p = parent[k]
                for u in self.adj(k):
                    if u != p:
                        parent[u] = k
                        stack.append(u)
            self._parent = parent
            return parent[v]

    def children(self, v):
        try:
            return self._children[v]
        except AttributeError:
            children = [[] for _ in range(self.n_vertices)]
            for u in range(self.n_vertices):
                p = self.parent(u)
                if p >= 0:
                    children[p].append(u)
            self._children = children
            return children[v]

    @property
    def edges(self):
        try:
            return self._edges
        except AttributeError:
            for v in range(self.n_vertices):
                if v != self.root:
                    yield (v, self.parent(v))


def scc(graph, rgraph):
    n = graph.n_vertices
    order = []
    color = [0] * n
    for v0 in range(n):
        if color[v0]:
            continue
        color[v0] = -1
        stack = [iter(graph.adj(v0))]
        path = [v0]
        while path:
            for u in stack[-1]:
                if color[u] == 0:
                    color[u] = -1
                    path.append(u)
                    stack.append(iter(graph.adj(u)))
                    break
            else:
                v = path.pop()
                order.append(v)
                stack.pop()

    label = 0
    for v0 in reversed(order):
        if color[v0] >= 0:
            continue
        color[v0] = label
        stack = [v0]
        while stack:
            v = stack.pop()
            for u in rgraph.adj(v):
                if color[u] < 0:
                    color[u] = label
                    stack.append(u)
        label += 1
    return label, color


def dijkstra(graph: BaseWeightedGraph, s: Union[int, Iterable[int]], t: Union[int, Iterable[int]] = -1,
             inf: Any = 2 ** 62) -> Tuple[List[int], Any]:
    """
    Returns a list of distance. If starts contains more than one vertex, returns the shortest distance from any of them.
    """
    K = graph.n_vertices.bit_length()
    MASK = (1 << K) - 1
    dist = [inf] * graph.n_vertices

    if isinstance(s, int):
        q = [s]
        dist[s] = 0
    else:
        q = list(s)
        for v in q:
            dist[v] = 0
    if isinstance(t, int):
        if t < 0:
            t = []
        else:
            t = [t]
    else:
        t = set(t)

    while q:
        x = hq.heappop(q)
        d, v = x >> K, x & MASK
        if v in t:
            return dist, d
        if d > dist[v]:
            continue
        for u, w in graph.wadj(v):
            if dist[u] > d + w:
                dist[u] = d + w
                hq.heappush(q, ((d + w) << K) | u)
    return dist, None


def dijkstra_general(graph: BaseWeightedGraph, inf: Any, zero: Any, s: Union[int, Iterable[int]],
                     t: Union[int, Iterable[int]] = -1) -> Tuple[List[Any], Any]:
    """
    Returns a list of distance. If starts contains more than one vertex, returns the shortest distance from any of them.
    """
    dist = [inf] * graph.n_vertices

    if isinstance(s, int):
        q = [(zero, s)]
        dist[s] = zero
    else:
        q = [(zero, v) for v in s]
        for d, v in q:
            dist[v] = zero
    if isinstance(t, int):
        if t < 0:
            t = []
        else:
            t = [t]
    else:
        t = set(t)

    while q:
        d, v = hq.heappop(q)
        if v in t:
            return dist, d
        if d > dist[v]:
            continue
        for u, w in graph.wadj(v):
            nw = d + w
            if dist[u] > nw:
                dist[u] = nw
                hq.heappush(q, (nw, u))
    return dist, None


