def rerooting(rooted_tree, merge, identity, finalize):
    """
    merge: (T,T) -> T, (T, merge)はモノイド
    identity: 単位元
    finalize: (T, V, V) -> T

    以下の形で書けるdpは対応可能
    dp[u,v] = finalize(merge(dp[v,k] for k in adj[v] if k != u), u, v)
    ただし(u,v)は辺 u->v
    """
    N = rooted_tree.n_vertices
    parent = rooted_tree.parent
    children = rooted_tree.children
    order = rooted_tree.dfs_order

    # from leaf to parent
    dp_down = [None] * N
    for v in reversed(order):
        dp_down[v] = finalize(reduce(merge,
                                     (dp_down[c] for c in children[v]),
                                     identity), parent[v], v)

    # from parent to leaf
    dp_up = [None] * N
    dp_up[0] = identity
    for v in order:
        if len(children[v]) == 0:
            continue
        temp = (dp_up[v],) + tuple(dp_down[u] for u in children[v]) + (identity,)
        left = accumulate(temp[:-2], merge)
        right = tuple(accumulate(reversed(temp[2:]), merge))
        for u, l, r in zip(children[v], left, reversed(right)):
            dp_up[u] = finalize(merge(l, r), u, v)

    res = [None] * N
    for v, l in enumerate(children):
        res[v] = reduce(merge,
                        (dp_down[u] for u in children[v]),
                        identity)
        res[v] = merge(res[v], dp_up[v])
    return res, dp_up, dp_down


def longest_increasing_sequence(l, inf):
    dp = [inf] * len(l)
    for i, v in enumerate(l):
        dp[bisect.bisect(dp, v)] = i

    m = next(n for n in reversed(range(len(l))) if dp[n] < inf) + 1
    return m


def zeta(data, merge):
    """
    （この関数はdataを上書きします）
    Mはモノイド
    data: 2^n -> M
    output: 2^n -> M
    merge: M -> M

    ouput[i] = sum(data[j] for j in range(2^n) if i|j == i)
    """
    n = len(data)
    while i < n:
        j = i
        while j < n:
            data[j] = merge(data[j], data[j & ~i])
            j = (j + 1) | i
        i <<= 1
    return data


def check_bipartiteness(n_vertices, edges):
    ds = DisjointSet(2 * n_vertices)

    for a, b in edges:
        ds.union(a, b + n_vertices)
        ds.union(b, a + n_vertices)

    next_color = 0
    color = [-1] * (2 * n_vertices)
    for v in range(n_vertices):
        ra = ds.find(v)
        rb = ds.find(v + n_vertices)
        if ra == rb:
            return None
        if color[ra] < 0:
            color[ra] = next_color
            color[rb] = next_color + 1
            next_color += 2
        color[v] = color[ra]
        color[v + n_vertices] = color[rb]
    return color[:n_vertices]


def small_range_duplicate(a):
    MASK = (1 << 32) - 1
    n = len(a)
    left = [i - 1 for i in range(n + 1)]
    right = [i + 1 for i in range(n + 1)]

    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    t = 0
    vi = sorted_ind[t]
    i = vi & MASK
    v = ~(vi >> 32)
    while t < n:
        j = i
        l = left[i]
        pi = l
        pv = v
        while v == pv and left[i] == pi:
            pi = i
            t += 1
            if t >= n:
                break
            vi = sorted_ind[t]
            i = vi & MASK
            v = ~(vi >> 32)
        r = right[pi]
        right[l] = r
        while j <= pi:
            nj = right[j]
            left[j] = l
            right[j] = r
            j = nj
        left[r] = l

    return left, right


def small_range(a):
    N = len(a)
    MASK = (1 << 32) - 1
    left = [i - 1 for i in range(N + 1)]
    right = [i + 1 for i in range(N + 1)]
    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    for v in sorted_ind:
        i = v & MASK
        left[right[-i]] = left[-i]
        right[left[-i]] = right[-i]

    return left, right


def popcnt32(n):
    n = n - ((n >> 1) & 0x55555555)
    n = (n & 0x33333333) + ((n >> 2) & 0x33333333)
    return ((((n + (n >> 4)) & 0x0f0f0f0f) * 0x01010101) >> 24) & 0xff


def popcnt64(n):
    n = n - ((n >> 1) & 0x5555555555555555)
    n = (n & 0x3333333333333333) + ((n >> 2) & 0x3333333333333333)
    n = (n + (n >> 4)) & 0x0f0f0f0f0f0f0f0f
    return ((((n + (n >> 32)) & 0xffffffff) * 0x01010101) >> 24) & 0xff


def popcnt(n):
    if n < 1 << 32:
        return popcnt32(n)
    elif n < 1 << 64:
        return popcnt64(n)
    else:
        return sum(c == '1' for c in bin(n))


def reverse_bits32(x):
    x = ((x & 0x55555555) << 1) | ((x & 0xAAAAAAAA) >> 1)
    x = ((x & 0x33333333) << 2) | ((x & 0xCCCCCCCC) >> 2)
    x = ((x & 0x0F0F0F0F) << 4) | ((x & 0xF0F0F0F0) >> 4)
    x = ((x & 0x00FF00FF) << 8) | ((x & 0xFF00FF00) >> 8)
    return ((x & 0x0000FFFF) << 16) | ((x & 0xFFFF0000) >> 16)


def count_inversions(l: List[Any]) -> int:
    """
    転倒数を計算する。in-placeでソートもする。

    :param l: リスト
    :return: 転倒数
    """
    bit = BinaryIndexedTree(len(l))
    res = 0
