        res += bit[v + 1:]
    return res


class BinaryTrie:
    class Node:
        def __init__(self):
            self.zero = None
            self.one = None
            self.cnt = 0

    def __init__(self, bits):
        self.root = self.Node()
        self.bits = bits

    def add(self, v):
        n = self.root
        n.cnt += 1
        for d in reversed(range(self.bits)):
            if (v >> d) & 1:
                if not n.one:
                    n.one = self.Node()
                n = n.one
            else:
                if not n.zero:
                    n.zero = self.Node()
                n = n.zero
            n.cnt += 1

    def remove(self, v):
        n = self.root
        n.cnt -= 1
