def main():
    N = int(input())
    Graph = [[] for _ in range(N)]
    for i in range(N):
        v = int(input())
        Graph[i].append(v-1)
    s = 0 # start vertex 0
    dist = [-1] * N
    dist = BFS(Graph, s, dist)
    if dist[1] == -1:
        print(-1)
    else:
        print(dist[1])

def BFS(Graph: list, s: int, dist: list):
    # initialize
    dist[s] = 0
    todo = deque([s])
    while todo:
        v = todo.popleft()
        for vp in Graph[v]:
            if dist[vp] != -1:
                continue
            dist[vp] = dist[v] + 1
            todo.append(vp)
    return dist

