def bellman_ford(s, n, w, es):    
    # s:始点, n:頂点数, w:辺の数, es[i]: [辺の始点,辺の終点,辺のコスト]    
    INF = 10**18
    flag = False
    d = [INF]*n
    d[s] = 0  #d[i]: iまでの最短距離
    update = True
    update_counter = np.zeros(n)
    for _ in range(2*n):
        update_count_cyc = np.zeros(n)
        update = False
        for i, j, c in es:
            if d[i] != INF and d[j] > d[i]+c:
                d[j] = d[i] + c
                update = True
                update_count_cyc[j] = 1
        update_counter += update_count_cyc
        if not update:
            break
    else:
        flag = True
    return flag, d, update_counter

