def shortest_path(s, n, es):
    # s→iの最短距離
    # s:始点, n:頂点数, es[i]: [辺の始点,辺の終点,辺のコスト]

    # 重みの初期化。ここに最短距離をメモしていく
    d = [float("inf")] * n

    # スタート地点は0
    d[s] = 0

    # 最短路を計算
    for _ in range(n-1):
        # es: 辺iについて [from,to,cost]
        for p, q, r in es:
            # 矢印の根が探索済、かつコストができるルートがあれば更新
            if d[p] != float("inf") and d[q] > d[p] + r:
                d[q] = d[p] + r

    # 負閉路をチェック
    for _ in range(n-1):
        # e: 辺iについて [from,to,cost]
        for p, q, r in es:
            # 更新される点は負閉路の影響を受けるので-infを入れる
            if d[q] > d[p] + r:
                d[q] = -float("inf")

    if d[-1] != float("inf") and d[-1] != -float("inf"):
        print(-d[-1])
    else:
        print("inf")


