  class Graph:
    class __Edge:
      def __init__(self, weight=1, capacity=1, **args):
        self.weight = weight
        self.capacity = capacity

      def __str__(self):
        return f'weight: {self.weight}, cap: {self.capacity}'

    class __Node:
