def read():
    N = int(input().strip())
    S = []
    for i in range(N):
        s = int(input().strip())
        S.append(s)
    return N, S


def bugged_score(s):
    if s % 10 == 0:
        return 0
    else:
        return s


def solve(N, S):
    T = [0 for i in range(N+1)]
    for i in range(N):
        T[i+1] = T[i] + S[i]
    # 全て正解のとき
    ans = bugged_score(T[N])
    for i in range(1, N+1):
        # i番目の問題を不正解とするとき
        l = T[i-1] - T[0]
        r = T[N] - T[i]
        a = bugged_score(l + r)
        ans = max(ans, a)
    return ans


