def resolve():
    N = int(input())
    s = []
    for _ in range(N):
        s.append(int(input()))

    def f(cutoff):
        summ = sum(s)
        minn = min(s)
        if summ % 10 != 0:
            print(summ + cutoff)
            return
        if summ == minn:
            print(0)
            return
        s.remove(minn)
        if minn % 10 == 0:
            return f(cutoff+minn)
        return f(cutoff)

    return f(0)


