#少ない1行のint変数に入れる様の入力．例:N, A, B = map(int, sys.stdin.readline().split())
def MI(): return map(int, sys.stdin.readline().split())
def solve():
    W,H,N = MI()
    Space = [[1 for i in range(W)] for i in range(H)]
    X_right = 0
    X_left = W
    Y_Up = H
    Y_Down = 0
    for i in range(N):
        x,y,a = MI()
        if(a==1):
            if(X_right < x):
                X_right = x
        if(a==2):
            if(x < X_left):
                X_left = x
        if(a==3):
            if(Y_Down < y):
                Y_Down = y
        if(a==4):
            if(y < Y_Up):
                Y_Up = y
    import pprint
    for i in range(H):
        for j in range(X_right):
            Space[i][j] = 0
        for j in range(X_left , W):
            Space[i][j] = 0
    for j in range(W):
        for i in range(Y_Down):
            Space[i][j] = 0
        for i in range(Y_Up , H):
            Space[i][j] = 0
    ans = 0
    for i in range(H):
        ans += Space[i].count(1)
    print(ans)
    return
solve()

