def acc(arr, M, inizero = False):
    a = [0]
    for ar in arr:
        a.append((a[-1] + ar) % M)
    if not inizero:
        a = a[1:]
    return a

def main():
    f = sys.stdin
    W, H, N = map(int, f.readline().split())
    xya = [list(map(int, f.readline().split())) for i in range(N)]
    tbl = [[1] * W for i in range(H)]

    for n in range(N):
        x, y, a = xya[n]
        if a == 1:
            for i in range(H):
                for j in range(x):
                    tbl[i][j] = 0
        elif a == 2:
            for i in range(H):
                for j in range(x, W):
                    tbl[i][j] = 0
        elif a == 3:
            for i in range(y):
                for j in range(W):
                    tbl[i][j] = 0
        else:
            for i in range(y, H):
                for j in range(W):
                    tbl[i][j] = 0

    ans = 0
    for i in range(H):
        for j in range(W):
            ans += tbl[i][j]
    return ans

