def input_i_lc(N):
    li = [list(map(int, input().split())) for _ in range(N)]
    return (li)


def two_dimension_gen(x, y):
    l = np.zeros((x, y))
    return l


# --solve--#
def solve():
    W, H, N = map(int, input().split())
    l = input_i_lc(N)
    rec = two_dimension_gen(H,W)

    for i in range(N):
        if l[i][-1] == 1:
            rec[:,0:l[i][0]] = 1
        elif l[i][-1] == 2:
            rec[:,l[i][0]:W] = 1
        elif l[i][-1] == 3:
            rec[0:l[i][1],:] = 1
        elif l[i][-1] == 4:
            rec[l[i][1]:H,:] = 1
        else:
            exit()

    print(np.sum(rec == 0))

