import numpy as np


def solve(canvas, q, h, w):
    if q[2] == 1:
        canvas[0:h, 0:q[0]] = 1
    elif q[2] == 2:
        canvas[0:h, q[0]:w] = 1
    elif q[2] == 3:
        canvas[0:q[1], 0:w] = 1
    else:
        canvas[q[1]:h, 0:w] = 1

    return canvas


