        return self.find(x) == self.find(y)

    def get_size(self, x):
        x = self.find(x)
        return self.size[x]


def kruskal(n, edges):
    """
    Solve Minimum Spanning Tree by Kruskal's algorithm.
    :param n: Number of nodes
    :param edges: [u, v, cost]
    :return: Total cost
    """
    edges.sort(key=lambda x: x[2])
    uf = UnionFind(n)
    total_cost = 0
    for u, v, c in edges:
        if not uf.is_same(u, v):
            total_cost += c
            uf.union(u, v)
    return total_cost


