class UnionFind():
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * (n + 10)

    def find(self, x):
        if self.parents[x] < 0:
            return x
        else:
            self.parents[x] = self.find(self.parents[x])
            return self.parents[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        else:
            if self.parents[x] < self.parents[y]:
                self.parents[x] += self.parents[y]
                self.parents[y] = x
            else:
                self.parents[y] += self.parents[x]
                self.parents[x] = y

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def size(self, x):
        return - self.parents[self.find(x)]


