def kruskal(n,E): #Eには[重さ・辺の端頂点1・辺の端頂点2]の順のリストがn個格納されている。
  E.sort()
  cnt=0
  weigh=0
  uf=UnionFind(n)
  for w,v1,v2 in E:
    if not uf.same(v1,v2):
      uf.union(v1,v2)
      cnt+=1
      weigh+=w
    if cnt==n-1:
      break
  return weigh

