            # 根を引数に取るとサイズを返す
        if self.parents[x] < 0:
            return x
        else:
            # 根を調べると、親が根に更新される（経路圧縮）
            # printやmenbersで呼び出されて実行されるので注意
            self.parents[x] = self.root(self.parents[x])
            return self.parents[x]

