class UnionFind():
    def __init__(self, n):
        self.n = n
        self.par = [-1] * n
        self.siz = [1] * n

    def root(self, x):
        if self.par[x] == -1:
            return x
        else:
            self.par[x] = self.root(self.par[x])
            return self.par[x]

    def issame(self, x, y):
        if self.root(x) == self.root(y):
          result_issame = True
        else:
          result_issame = False

        return result_issame

    def unite(self, x, y):
        x = self.root(x)
        y = self.root(y)

        #すでに同じグループの場合は何もしない
        if x == y: return False

        #union by size にできるように、頂点の数が小さい方を大きい方に併合するように処理を分ける
        if self.siz[x] > self.siz[y]:
          self.par[y] = x
          self.siz[x] += self.siz[y]
          return True
        else:
          self.par[x] = y
          self.siz[y] += self.siz[x]
          return True

    def size(self, x):
        return self.siz[self.root(x)]

    def all_group_members(self):
        group_members = defaultdict(list)
        for member in range(self.n):
            group_members[self.root(member)].append(member)
        return group_members
    def __str__(self):
        return '\n'.join(f'{r}: {m}' for r, m in self.all_group_members().items())

