    X.sort()
    Y.sort()
    edges_dict = {}
    INF = 10 ** 9
    for Z in (X, Y):
        for i in range(N-1):
            z1, i1 = Z[i]
            z2, i2 = Z[i+1]
            if i1 > i2:
                i1, i2 = i2, i1
            edges_dict[(i1, i2)] = min(edges_dict.get((i1, i2), INF), z2 - z1)

    edges = []
    for (i1, i2), dist in edges_dict.items():
        edges.append((dist, i1, i2))
    edges.sort()

    uf = UnionFind(N)
    ans = 0
    for dist, i1, i2 in edges:
        if uf.is_united(i1, i2):
            continue
        uf.unite(i1, i2)
        ans += dist

    print(ans)


