            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y:
            return False
        if x > y:
            x, y = y, x

        self.par[x] += self.par[y]
        self.par[y] = x
        return True

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def size(self, x):
        return -self.par[self.find(x)]

    def roots(self):
        return [i for i in range(1, self.N + 1) if self.par[i] < 0]

    def members(self, x):
        p = self.find(x)
        return [i for i in range(1, self.N + 1) if self.find(i) == p]

    def groups(self):
        return [self.members(p) for p in self.roots()]


