def clascal(N, E, tree_count=1):
    #E[weight, vertical, vertical]
    tree = UnionFind(N)
    weight = 0
    counter = 0
    # E[w, A, B]
    for e in sorted(E):
        if counter >= N-1:
            break
        if tree.ifSame(e[1], e[2]):
            continue
        else:
            tree.unite(e[1], e[2])
            weight += e[0]
            counter += 1
    return weight


