def read():
    S = input().strip()
    return S,


def solve(S):
    N = len(S)
    # dp[i]: i桁目までの数字の和
    dp = [0 for i in range(N+1)]
    for i in range(1, N+1):
        for j in range(i):
            c = 2**(j-1) if j > 0 else 1
            dp[i] += dp[j] + int(S[j:i]) * c
    return dp[N]


