        self.city = city
        self.roads = roads
        self.counter = {}
        self.count_roads()
        self.answer()
    def count_roads(self):
        for i in roads:
            for j in i:
                if j in self.counter:
                    self.counter[j] += 1
                else:
                    self.counter[j] = 1
    def answer(self):
