from typing import List, Tuple

def empty_graph(n: int, m: int) -> List[List[int]]:
    graph = []
    for _ in range(n):
        graph.append([ 0 for _ in range(m) ])

    return graph

def solve(num_cities: int, num_roads: int, roads: List[Tuple[int, int]]) -> str:
    connected_cities_graph = empty_graph(num_cities, num_cities)

    for i in range(num_roads):
        a_i, b_i = roads[i]
        connected_cities_graph[a_i-1][b_i-1] += 1
        connected_cities_graph[b_i-1][a_i-1] += 1

    num_connected_roads = [ sum(connected_cities) for connected_cities in connected_cities_graph ]

    return '\n'.join(map(str, num_connected_roads))

